CREATE TABLE IF NOT EXISTS watch_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, provider_id TEXT NOT NULL, media_id TEXT NOT NULL, episode_id TEXT NOT NULL DEFAULT '', title TEXT, episode_title TEXT, poster TEXT, media_type TEXT, genres JSONB NOT NULL DEFAULT '[]'::jsonb, position_seconds DOUBLE PRECISION NOT NULL DEFAULT 0, duration_seconds DOUBLE PRECISION NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (user_id, media_id, episode_id))